import React, { useEffect, useState } from 'react';
import { fetchReviews } from '../api/reviewApi';
import axios from '../api/axiosConfig';

// 이미지 import
import minjiImg from '../assets/minji.jpg';
import suaImg from '../assets/sua.jpg';
import chaeheeImg from '../assets/chaehee.jpg';

function Magazine() {
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(false);
  const [hoveredReviewer, setHoveredReviewer] = useState(null);

  // 급상승 리뷰어 데이터
  const topReviewers = [
    {
      id: 1,
      name: '뷰티민지',
      avatar: minjiImg,
      specialty: '뷰티',
      followerGain: 324,
      quote: '진정성 있는 리뷰가 제 원칙이에요'
    },
    {
      id: 2,
      name: '스킨케어수아',
      avatar: suaImg,
      specialty: '스킨케어',
      followerGain: 287,
      quote: '민감한 피부를 위한 꿀팁 공유해요'
    },
    {
      id: 3,
      name: '인플루언서채희',
      avatar: chaeheeImg,
      specialty: '퍼퓸 & 프래그런스',
      followerGain: 198,
      quote: '데일리룩 추천은 저에게 맡겨주세요'
    }
  ];

  useEffect(() => {
    const load = async () => {
      try {
        setLoading(true);
        const reviewsRes = await fetchReviews({ page: 1, limit: 8 });
        const texts = reviewsRes.data.map(r => r.text);
        const resp = await axios.post('/ai/summarize', { texts });
        setSummary(resp.data.summary);
      } catch (err) {
        console.error('magazine load failed', err);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  return (
    <div 
      style={{ 
        padding: 20, 
        minHeight: '100vh',
        background: 'linear-gradient(180deg, #fff 0%, #fff5f7 50%, #faf5ff 100%)',
        position: 'relative'
      }}
    >
      <h1>📰 AI 리뷰 매거진</h1>
      <p style={{ color: '#666' }}>AI가 여러 리뷰를 뽑아 트렌드와 핵심을 정리해드립니다.</p>

      {/* 급상승 리뷰어 섹션 - SNS 스타일 */}
      <div style={{ maxWidth: 1000, margin: '40px auto' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 24 }}>
          <span style={{ fontSize: 24 }}>🚀</span>
          <div>
            <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: '#1a1a2e' }}>급상승 리뷰어</h2>
            <p style={{ margin: 0, color: '#888', fontSize: 13 }}>이번 주 주목할 크리에이터</p>
          </div>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 20 }}>
          {topReviewers.map((reviewer, idx) => (
            <div
              key={reviewer.id}
              onMouseEnter={() => setHoveredReviewer(reviewer.id)}
              onMouseLeave={() => setHoveredReviewer(null)}
              style={{
                borderRadius: 20,
                overflow: 'hidden',
                boxShadow: hoveredReviewer === reviewer.id 
                  ? '0 16px 40px rgba(0,0,0,0.2)' 
                  : '0 4px 20px rgba(0,0,0,0.1)',
                transition: 'all 0.4s ease',
                transform: hoveredReviewer === reviewer.id ? 'translateY(-8px) scale(1.02)' : 'translateY(0) scale(1)',
                cursor: 'pointer',
                background: '#fff'
              }}
            >
              {/* 프로필 이미지 영역 - 큰 배경 */}
              <div style={{
                width: '100%',
                height: 280,
                position: 'relative',
                overflow: 'hidden'
              }}>
                <img 
                  src={reviewer.avatar} 
                  alt={reviewer.name}
                  style={{ 
                    width: '100%', 
                    height: '100%', 
                    objectFit: 'cover',
                    transition: 'transform 0.4s ease'
                  }}
                  onMouseOver={e => e.currentTarget.style.transform = 'scale(1.05)'}
                  onMouseOut={e => e.currentTarget.style.transform = 'scale(1)'}
                />
                
                {/* 그라데이션 오버레이 */}
                <div style={{
                  position: 'absolute',
                  bottom: 0,
                  left: 0,
                  right: 0,
                  height: '50%',
                  background: 'linear-gradient(transparent, rgba(0,0,0,0.7))',
                  pointerEvents: 'none'
                }} />

                {/* 1위 뱃지 */}
                {idx === 0 && (
                  <div style={{
                    position: 'absolute',
                    top: 12,
                    right: 12,
                    background: 'linear-gradient(135deg, #ff6b9d, #ff8a65)',
                    color: 'white',
                    padding: '6px 12px',
                    borderRadius: 20,
                    fontSize: 12,
                    fontWeight: 700,
                    boxShadow: '0 4px 12px rgba(255,107,157,0.4)'
                  }}>
                    🏆 1위
                  </div>
                )}

                {/* 이름 라벨 (이미지 위) */}
                <div style={{
                  position: 'absolute',
                  top: 12,
                  left: 12,
                  display: 'flex',
                  alignItems: 'center',
                  gap: 6,
                  background: 'rgba(255,255,255,0.95)',
                  borderRadius: 20,
                  padding: '6px 14px',
                  boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
                }}>
                  <span style={{ fontSize: 12 }}>🌿</span>
                  <span style={{ fontSize: 12, fontWeight: 600, color: '#2e7d32' }}>{reviewer.name}</span>
                </div>

                {/* 하단 오버레이 정보 */}
                <div style={{
                  position: 'absolute',
                  bottom: 16,
                  left: 16,
                  right: 16,
                  color: 'white'
                }}>
                  <h3 style={{ margin: 0, fontSize: 20, fontWeight: 800, textShadow: '0 2px 4px rgba(0,0,0,0.3)' }}>
                    {reviewer.name}
                  </h3>
                  <p style={{ margin: '4px 0 0', fontSize: 13, opacity: 0.9 }}>
                    {reviewer.specialty} 전문
                  </p>
                </div>
              </div>

              {/* 하단 정보 영역 */}
              <div style={{ padding: '16px 20px' }}>
                {/* 팔로워 증가 */}
                <div style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: 8,
                  background: 'linear-gradient(135deg, #e8f5e9, #c8e6c9)',
                  padding: '10px 16px',
                  borderRadius: 12,
                  marginBottom: 14
                }}>
                  <span style={{ color: '#2e7d32', fontWeight: 600, fontSize: 14 }}>팔로워</span>
                  <span style={{ color: '#43a047', fontWeight: 800, fontSize: 16 }}>+{reviewer.followerGain}</span>
                </div>

                {/* 한 마디 */}
                <p style={{ 
                  margin: 0,
                  color: '#555', 
                  fontSize: 13, 
                  fontStyle: 'italic', 
                  lineHeight: 1.5,
                  textAlign: 'center',
                  padding: '0 8px'
                }}>
                  "{reviewer.quote}"
                </p>

                {/* 팔로우 버튼 */}
                <button style={{
                  width: '100%',
                  marginTop: 14,
                  padding: '12px',
                  borderRadius: 12,
                  border: 'none',
                  background: 'linear-gradient(135deg, #ff6b9d, #c44cff)',
                  color: 'white',
                  fontWeight: 700,
                  fontSize: 14,
                  cursor: 'pointer',
                  transition: 'all 0.3s ease'
                }}
                onMouseOver={e => e.currentTarget.style.opacity = '0.9'}
                onMouseOut={e => e.currentTarget.style.opacity = '1'}
                >
                  + 팔로우
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {loading && <p>요약 생성 중...</p>}

      {summary && (
        <div style={{ marginTop: 16, padding: 16, background: '#fff', borderRadius: 8, boxShadow: '0 8px 20px rgba(0,0,0,0.04)' }}>
          <div dangerouslySetInnerHTML={{ __html: summary.replace(/\n/g, '<br/>') }} />
        </div>
      )}
    </div>
  );
}

export default Magazine;
